CREATE OR REPLACE FUNCTION sharawla_internal.current_operational_profile_v1()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'sharawla_internal'
AS $function$
declare
  v_count integer;
  v_profile text;
begin
  select count(*),max(trim(profile_code))
    into v_count,v_profile
  from sharawla_internal.operational_business_identity_v1;

  if v_count<>1 or v_profile is null or v_profile='' then
    raise exception 'OPERATIONAL_PROFILE_BINDING_MISSING';
  end if;

  return lower(v_profile);
end;
$function$

CREATE OR REPLACE FUNCTION sharawla_internal.operational_feature_entitled_v1(p_feature_code text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'sharawla_internal'
AS $function$
declare
  v_feature text:=lower(trim(coalesce(p_feature_code,'')));
  v_business uuid;
begin
  if v_feature='' then
    return false;
  end if;

  v_business:=sharawla_internal.current_operational_business_id_v1();

  return exists(
    select 1
    from sharawla_internal.operational_feature_entitlements_v1 e
    where e.cloud_business_id=v_business
      and e.feature_code=v_feature
      and e.enabled=true
      and (e.valid_until is null or e.valid_until>pg_catalog.statement_timestamp())
  );
end;
$function$

CREATE OR REPLACE FUNCTION sharawla_internal.role_action_default_state_v2(p_profile_code text, p_role_code text, p_action_code text)
 RETURNS TABLE(table_available boolean, default_found boolean, default_allowed boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'sharawla_internal'
AS $function$
declare
  v_allowed boolean;
  v_count bigint:=0;
begin
  if pg_catalog.to_regclass('public.permission_role_action_defaults_v2') is null then
    return query select false,false,null::boolean;
    return;
  end if;

  execute
    'select d.allowed
       from public.permission_role_action_defaults_v2 d
      where d.profile_code=$1
        and d.role_code=$2
        and d.action_code=$3
        and d.active=true
      limit 1'
    into v_allowed
    using lower(trim(coalesce(p_profile_code,''))),
          lower(trim(coalesce(p_role_code,''))),
          lower(trim(coalesce(p_action_code,'')));

  get diagnostics v_count=row_count;

  if v_count>0 then
    return query select true,true,v_allowed;
  else
    return query select true,false,null::boolean;
  end if;
end;
$function$
